/// Per-glyph advances in pixels, regular weight, indexed by
/// `glyph_index(c)`.
pub const ADVANCE: [u8; 95] = [6, 6, 8, 13, 12, 15, 13, 4, 8, 8, 10, 12, 5, 6, 6, 9, 11, 11, 11, 11, 11, 11, 11, 11, 11, 11, 6, 5, 11, 11, 11, 10, 16, 14, 13, 14, 14, 12, 12, 14, 15, 6, 12, 13, 11, 16, 15, 14, 13, 14, 13, 12, 12, 13, 13, 16, 13, 13, 13, 6, 9, 6, 9, 10, 7, 11, 12, 11, 12, 11, 8, 12, 12, 5, 5, 11, 5, 16, 12, 12, 12, 12, 7, 11, 7, 12, 10, 16, 11, 10, 11, 7, 6, 7, 14];

/// Per-glyph advances for the bold weight: one wider than regular
/// for every glyph with ink, because the stems are one pixel thicker.
pub const ADVANCE_BOLD: [u8; 95] = [6, 7, 9, 14, 13, 16, 14, 5, 9, 9, 11, 13, 6, 7, 7, 10, 12, 12, 12, 12, 12, 12, 12, 12, 12, 12, 7, 6, 12, 12, 12, 11, 17, 15, 14, 15, 15, 13, 13, 15, 16, 7, 13, 14, 12, 17, 16, 15, 14, 15, 14, 13, 13, 14, 14, 17, 14, 14, 14, 7, 10, 7, 10, 11, 8, 12, 13, 12, 13, 12, 9, 13, 13, 6, 6, 12, 6, 17, 13, 13, 13, 13, 8, 12, 8, 13, 11, 17, 12, 11, 12, 8, 7, 8, 15];
// <<< generated block ends above this line
pub const FALLBACK_ADVANCE: usize = 6;

#[inline]
pub fn glyph_index(c: u8) -> Option<usize> {
    if (FIRST_CHAR..=LAST_CHAR).contains(&c) {
        Some((c - FIRST_CHAR) as usize)
    } else {
        None
    }
}

#[inline]
pub fn advance_of(c: u8, bold: bool) -> usize {
    match glyph_index(c) {
        Some(i) => {
            if bold {
                ADVANCE_BOLD[i] as usize
            } else {
                ADVANCE[i] as usize
            }
        }
        None => FALLBACK_ADVANCE,
    }
}

#[inline]
pub fn glyph_rows(c: u8, bold: bool) -> Option<&'static [u16]> {
    let i = glyph_index(c)?;
    let table: &[u16] = if bold { &FONT_BOLD } else { &FONT };
    Some(&table[i * GLYPH_H..i * GLYPH_H + GLYPH_H])
}

#[inline]
pub fn pixel(c: u8, col: usize, row: usize, bold: bool) -> bool {
    if col >= GLYPH_W || row >= GLYPH_H {
        return false;
    }
    match glyph_rows(c, bold) {
        Some(rows) => (rows[row] >> (GLYPH_W - 1 - col)) & 1 == 1,
        None => {
            if c != b' ' && c != 0 && c != b'\n' && c != b'\r' && c != b'\t' {
                let w = FALLBACK_ADVANCE;
                if col < w && row >= CAP_TOP && row <= BASELINE {
                    return col == 0 || col == w - 1 || row == CAP_TOP || row == BASELINE;
                }
            }
            false
        }
    }
}

/// Coverage of the glyph pixel at `(col, row)` as a 4-bit level 0..=15.
///
/// This is the anti-aliasing source: `test_text_aa` blends `color` toward `bg`
/// with `level * 17` alpha, a sixteen-step ramp, so glyph edges land on
/// intermediate tones instead of on hard on/off pixels. The binary view is
/// `level >= 8`, which is exactly `pixel` and matches the 1-bit threshold the
/// generator bakes into `FONT` and `FONT_BOLD`, so layout maths and rendering
/// cannot disagree about ink.
#[inline]
pub fn coverage(c: u8, col: usize, row: usize, bold: bool) -> u32 {
    if col >= GLYPH_W || row >= GLYPH_H {
        return 0;
    }
    let table: &[u64] = if bold { &FONT_COV_BOLD } else { &FONT_COV };
    match glyph_index(c) {
        Some(i) => ((table[i * GLYPH_H + row] >> (4 * (GLYPH_W - 1 - col))) & 0xF) as u32,
        None => {
            if c != b' ' && c != 0 && c != b'\n' && c != b'\r' && c != b'\t' {
                let w = FALLBACK_ADVANCE;
                if col < w && row >= CAP_TOP && row <= BASELINE {
                    if col == 0 || col == w - 1 || row == CAP_TOP || row == BASELINE {
                        return 15;
                    }
                }
            }
            0
        }
    }
}

/// The cap height, in pixels, that a rung of the scale ladder names.
///
/// WHY the rung names a cap height and not a cell multiple: the design
/// document writes its type scale in the sizes a reader sees -- a caption
/// of twelve to fourteen pixels, body text of fourteen, a title of
/// twenty-eight to thirty-two and a page heading of thirty-six to
/// forty-four -- while the rungs were multiples of the bitmap face's
/// sixteen-pixel cell, whose caps (seventeen, thirty-four, fifty-one,
/// a hundred and two) are more than twice the document's size for every
/// rung above the first. An app that took its size from the ladder
/// therefore drew text two and a half times the size the document asks
/// for, and every reserved box overflowed its neighbour: the classic
/// "everything overlaps, nothing has space" state the panel showed. The
/// rungs now name the document's sizes, and the bitmap face is the
/// fallback, not the source of truth.
///
/// The rungs sit at the top of each documented range, so outline text and the
/// bitmap caption keep a visible hierarchy instead of collapsing together on
/// a 720-wide surface.


/// The size a cap height the ladder produced was drawn at.
///
/// WHY a reverse map and not a division: the ladder's rungs are the design
/// document's font sizes, and a cap height is a rounded fraction of one, so
/// dividing back gives a different size than the rung the cap came from --
/// a nine-pixel cap is a twelve-pixel font, not an eleven-pixel one. Every
/// cap height a caller holds came from this ladder, so the map is exact for
/// the sizes the platform draws, and anything else falls back to the
/// generic conversion.
pub const fn em_for_cap_scale(cap_px: u32) -> u32 {
    let rungs = [1usize, 2, 3, 4, 5, 6, 7];
    let mut i = 0;
    while i < rungs.len() {
        if cap_px == cap_for_scale(rungs[i]) {
            return em_for_scale(rungs[i]);
        }
        i += 1;
    }
    crate::design::outline_text::em_for_cap_height(cap_px)
}

/// The size, in pixels of an em, a scale rung draws at.
///
/// WHY the rung names a font size and not a cap height: the design document
/// writes its type scale in the sizes a reader sees -- a caption of twelve,
/// body text of fifteen, a card title of eighteen, a title of twenty-six to
/// thirty and a hero clock of seventy-two -- and a cap height is a smaller
/// number for the same run (a cap is about seventy per cent of the em). A
/// ladder written in cap heights therefore drew every run a third larger
/// than the document asks for, and the app that reserved the document's
/// boxes drew text that did not fit them.
///
/// The values are the document's own: chips and badges at twelve, body at
/// fifteen, card and section titles at eighteen, a subheading at
/// twenty-two, a title at twenty-six, a page title at thirty and the hero
/// display at seventy-two.
pub const fn em_for_scale(scale: usize) -> u32 {
    // WHY the rung names a cap height and not a font size: the design
    // document writes its type scale in the sizes a reader sees, and
    // measuring the reference screens settles what those numbers are. On
    // the reference calculator the key labels stand fifteen pixels tall, the
    // title twenty-three and the result thirty-one, on a seven-hundred and
    // twenty pixel screen. Those numbers are cap heights, and the rungs are
    // the band [`cap_for_scale`] documents now.
    //
    // A ladder written in font sizes drew every run a third smaller than
    // the document asks for, and an app that reserved the document's boxes
    // drew text that did not fill them.
    let cap = cap_for_scale(scale);
    crate::design::outline_text::em_for_cap_height(cap)
}

/// The cap height, in pixels, that a scale rung draws at.
///
/// WHY these are the top of each documented range: the document gives a
/// range per role, and a phone held at reading distance sits at the large end
/// of it. The old rungs used the bottom of the body and section ranges, which
/// left outline text and the 13px bitmap caption within a pixel or two of
/// each other and flattened the hierarchy on every screen.
///
/// WHY the four lower rungs now sit above the range they were written in:
/// a type scale only means something relative to the panel it is read on, and
/// this one is read on a 720-pixel-wide panel. Measured as a share of the
/// panel's own width, the rungs a person compares this device against are
/// iOS's body at 3.00% (17pt of a 1206-wide panel, cap 36px), its footnote at
/// 2.30%, its title3 at 3.54% and its title1 at 4.95%; Android's body-large at
/// 2.77%, its label at 2.07%, and its 14sp body at 2.42%. The old ladder drew
/// a body cap of 18 here -- 2.50%, i.e. between Android's 14sp and its
/// body-large and 17% under iOS -- and a caption of 13, 1.81%, under every
/// label either platform ships. So the smallest text on this device was
/// smaller than the smallest text on a phone, which is what "the text is too
/// small" measured. Each of the four lower rungs then moved to the top of the
/// range its own role documents: caption 16 = 2.22%, body 21 = 2.92%, section
/// 27 = 3.75%, title 35 = 4.86% -- each inside the band the two platforms
/// actually occupy, and each still separated from its neighbour by more than
/// the 1.15x a hierarchy needs to read as three sizes rather than two. The
/// upper rungs are untouched: a heading of 44 is already 6.11% of the panel,
/// above iOS's 34pt large title at 5.95%.
///
/// caption 16, body 21, section 27, title 35, heading 44, display 56, hero
/// 76 -- with the hero rung above the display for a clock that is the whole
/// point of a lock screen.
///
/// WHY this stays the ladder itself, and does not read the text-size setting:
/// it is a `const fn` called from const contexts throughout the tree -- the
/// SDK's `typography::*_CAP_PX`, the ladder's own band table, and the
/// `const _: () = assert!(...)` gates in `webview`, the launcher and the
/// camera -- and a const evaluation cannot read a cell a person's setting
/// writes at run time. The setting is applied beside it, by
/// [`cap_for_scale_user`] and its family, which a surface that re-derives its
/// geometry at draw time calls. An application that wants the person's text
/// size publishes it once, where it already reads `display.text_scale`:
/// see [`crate::design::accessibility::DynamicType::publish`].
pub const fn cap_for_scale(scale: usize) -> u32 {
    match scale {
        1 => 16, // caption (15..=16)
        2 => 21, // body (19..=21)
        3 => 27, // card or section title (25..=27)
        4 => 35, // title (33..=35)
        5 => 44, // page heading (36..=44)
        6 => 56, // display (48..=56)
        7 => 76, // hero
        s => (s as u32).saturating_mul(13),
    }
}

/// User text scale levels for Dynamic Type / accessibility scaling.
/// - 0: Compact (80%)
/// - 1: Normal / Standard (100%)
/// - 2: Large (125%)
/// - 3: Extra Large (150%)
pub const TEXT_SCALE_COMPACT: u8 = 0;
pub const TEXT_SCALE_NORMAL: u8 = 1;
pub const TEXT_SCALE_LARGE: u8 = 2;
pub const TEXT_SCALE_EXTRA_LARGE: u8 = 3;

/// Scales a base cap height according to user text scale with bounds checking.
///
/// Bounds checking ensures text scales gracefully without collapsing below
/// minimum legible height (10px) or overflowing:
/// - 0: Compact (80% of normal cap height, bounded to min 10px)
/// - 1: Normal (100% of canonical cap height)
/// - 2: Large (125% of canonical cap height)
/// - 3: Extra Large (150% of canonical cap height)
/// - Any user_text_scale > 3 is clamped to 3 (extra large).
pub const fn scale_cap_height(base_cap: u32, user_text_scale: u8) -> u32 {
    if base_cap == 0 {
        return 0;
    }
    match user_text_scale {
        0 => {
            // Compact: 80% with 10px minimum bounds check
            let scaled = (base_cap * 80 + 50) / 100;
            if scaled < 10 {
                10
            } else {
                scaled
            }
        }
        1 => base_cap,
        2 => (base_cap * 125 + 50) / 100,
        _ => (base_cap * 150 + 50) / 100,
    }
}

/// The cap height, in pixels, for a given scale rung and user text scale level.
pub const fn cap_for_user_scale(scale: usize, user_text_scale: u8) -> u32 {
    let base_cap = cap_for_scale(scale);
    scale_cap_height(base_cap, user_text_scale)
}

/// Alias for `cap_for_user_scale` driving dynamic type scaling.
pub const fn cap_for_scale_with_user(scale: usize, user_text_scale: u8) -> u32 {
    cap_for_user_scale(scale, user_text_scale)
}

/// The em, in pixels, for a given scale rung and user text scale level.
pub const fn em_for_user_scale(scale: usize, user_text_scale: u8) -> u32 {
    let cap = cap_for_user_scale(scale, user_text_scale);
    crate::design::outline_text::em_for_cap_height(cap)
}

/// The line box, in pixels, for a given scale rung and user text scale level.
pub const fn line_height_for_user_scale(scale: usize, user_text_scale: u8) -> usize {
    if scale == 0 {
        return 0;
    }
    let em = em_for_user_scale(scale, user_text_scale);
    let (ascent, descent) = crate::design::typeface::line_metrics(em);
    (ascent + descent) as usize
}

/// The ascent, in pixels, for a given scale rung and user text scale level.
pub const fn ascent_for_user_scale(scale: usize, user_text_scale: u8) -> usize {
    let (ascent, _) = crate::design::typeface::line_metrics(em_for_user_scale(scale, user_text_scale));
    ascent as usize
}

/// Measures text advance under dynamic user text scaling.
pub fn measure_user_scale(text: &[u8], scale: usize, user_text_scale: u8) -> usize {
    match scale {
        0 => 0,
        s => {
            let em = em_for_user_scale(s, user_text_scale);
            crate::design::typeface::text_advance_px(text, em) as usize
        }
    }
}

/// Measures bold text advance under dynamic user text scaling.
pub fn measure_bold_user_scale(text: &[u8], scale: usize, user_text_scale: u8) -> usize {
    measure_user_scale(text, scale, user_text_scale) + usize::from(!text.is_empty())
}

// --- The published rung, and the helpers that draw at it ---------------------

/// The text-size level this process draws at, as a `UserTextScale` value: 0
/// compact, 1 normal, 2 large, 3 extra large.
///
/// WHY a static rather than an argument threaded inside [`cap_for_scale`]:
/// `cap_for_scale` is a `const fn` and is called from const contexts across
/// the tree -- this crate's own `typography::*_CAP_PX` and the
/// `LADDER_BANDS` table, the `const _: () = assert!(...)` gates in the
/// launcher and in `webview`, the camera's `SHEET_ACCENT_H` -- and a const
/// evaluation cannot read an atomic. Threading the rung inside it therefore
/// does not compile, and dropping `const` from it breaks every one of those
/// sites. The ladder stays the compile-time ladder and this cell carries the
/// person's setting beside it: the helpers below are the runtime faces of the
/// same arithmetic, and a layout that re-derives its boxes at draw time calls
/// them.
///
/// WHY the default is [`TEXT_SCALE_NORMAL`]: level one multiplies every cap by
/// one hundred per cent (`scale_cap_height` returns its argument), so an
/// application that never publishes a rung draws the pixels it drew before
/// this cell existed. Nothing here changes a box, a rung or an assertion until
/// an application calls [`set_user_text_scale`].
///
/// WHY one cell per process: every application links its own copy of this
/// static, so publishing a rung cannot resize another application's layout. An
/// application adopts the person's setting by reading `display.text_scale`
/// from the settings store -- the path it already polls -- and publishing what
/// it read. That is what this cell exists for; see
/// [`crate::design::accessibility::DynamicType::publish`].
pub static USER_TEXT_SCALE: core::sync::atomic::AtomicU8 =
    core::sync::atomic::AtomicU8::new(crate::font::TEXT_SCALE_NORMAL);

/// The level this process draws at: 0 compact, 1 normal, 2 large, 3 extra
/// large. See [`USER_TEXT_SCALE`].
#[inline]
pub fn user_text_scale() -> u8 {
    USER_TEXT_SCALE.load(core::sync::atomic::Ordering::Relaxed)
}

/// Hands the person's text-size setting to the renderer.
///
/// Returns the level actually stored. A level above [`TEXT_SCALE_EXTRA_LARGE`]
/// is stored as [`TEXT_SCALE_EXTRA_LARGE`] -- the ladder's largest setting --
/// so a caller can show the clamp it got rather than assume the number it
/// asked for was used.
///
/// WHY this is the only writer: the value comes from one place -- the
/// application's own poll of `display.text_scale` -- and a render path that
/// reads a cell with one writer and four readers costs nothing at draw time.
/// Reading it per glyph would put a settings query inside the paint loop,
/// which is not what a 60fps frame budget pays for; publishing it where the
/// setting is already read costs one store per refresh.
#[inline]
pub fn set_user_text_scale(level: u8) -> u8 {
    let stored = if level > TEXT_SCALE_EXTRA_LARGE {
        TEXT_SCALE_EXTRA_LARGE
    } else {
        level
    };
    USER_TEXT_SCALE.store(stored, core::sync::atomic::Ordering::Relaxed);
    stored
}

/// The cap height a rung draws at, at the published level.
///
/// The same arithmetic as [`cap_for_user_scale`] with the cached level in
/// place of the argument, so a call site that re-derives its geometry at draw
/// time never has to carry a `UserTextScale` through its own signature. At the
/// default level this returns [`cap_for_scale`]'s number exactly.
#[inline]
pub fn cap_for_scale_user(scale: usize) -> u32 {
    cap_for_user_scale(scale, user_text_scale())
}

/// The em a rung draws at, at the published level.
#[inline]
pub fn em_for_scale_user(scale: usize) -> u32 {
    em_for_user_scale(scale, user_text_scale())
}

/// The line box a rung reserves, at the published level.
///
/// WHY this exists beside [`cap_for_scale_user`]: a line box is the space a run
/// reserves, and a run drawn at a scaled cap inside an unscaled box is the
/// clipped-text class of defect this repo keeps being asked to fix. A caller
/// that moves its ink must move its box by the same rung, and this is the box
/// half of that pair.
#[inline]
pub fn line_height_user(scale: usize) -> usize {
    line_height_for_user_scale(scale, user_text_scale())
}

/// The ascent a rung reserves, at the published level.
#[inline]
pub fn ascent_for_scale_user(scale: usize) -> usize {
    ascent_for_user_scale(scale, user_text_scale())
}

/// The advance a run takes at the published level.
#[inline]
pub fn measure_user(text: &[u8], scale: usize) -> usize {
    measure_user_scale(text, scale, user_text_scale())
}

/// The advance a bold run takes at the published level.
#[inline]
pub fn measure_bold_user(text: &[u8], scale: usize) -> usize {
    measure_bold_user_scale(text, scale, user_text_scale())
}

/// A run's width at the published level, in the given weight.
#[inline]
pub fn measure_runs_user(runs: &[(&[u8], bool)], scale: usize) -> usize {
    runs.iter()
        .map(|&(text, bold)| {
            if bold {
                measure_bold_user(text, scale)
            } else {
                measure_user(text, scale)
            }
        })
        .sum()
}

/// The ascent, in pixels, of a run at the size a scale rung names.
///
/// WHY a function and not the bitmap's constant: a run's baseline now
/// comes from the typeface metrics at the rung's size, so a caller that
/// places a line box at `y0` and asks where the baseline sits gets the
/// same row the renderer places the ink on. `const` because app layout
/// constants and the `typography` styles are built in const contexts.
pub const fn ascent_for_scale(scale: usize) -> usize {
    let (ascent, _) = crate::design::typeface::line_metrics(em_for_scale(scale));
    ascent as usize
}

#[inline]
pub fn measure(text: &[u8], scale: usize) -> usize {
    match scale {
        0 => 0,
        s => {
            let em = em_for_scale(s);
            crate::design::typeface::text_advance_px(text, em) as usize
        }
    }
}

#[inline]
pub fn measure_bold(text: &[u8], scale: usize) -> usize {
    // The renderer dilates a bold run by one column in total, not per glyph,
    // so the measurement names the same width the ink paints.
    measure(text, scale) + usize::from(!text.is_empty())
}

/// The line box, in pixels, a run at `scale` reserves.
///
/// WHY these are the design document's values: a line box is the space a
/// run reserves, and it is a layout decision rather than a property of
/// the glyphs. The old `GLYPH_H * scale` values reserved two and a half
/// times the document's boxes, which is where the reserved space and the
/// neighbouring content collided.
pub const fn line_height(scale: usize) -> usize {
    // WHY the line box is the typeface's own at the rung's size and not a
    // fixed number per rung: a line box is the space a run reserves, and a
    // run reserves its ascent and its descent. The fixed numbers were the
    // bitmap cell's, and a run drawn with the outline face at a rung the
    // bitmap's numbers belonged to was taller than the box the layout
    // reserved for it, which is how two labels came to sit on top of one
    // another.
    if scale == 0 {
        return 0;
    }
    let em = em_for_scale(scale);
    let (ascent, descent) = crate::design::typeface::line_metrics(em);
    (ascent + descent) as usize
}

#[inline]
pub fn center_x(text: &[u8], scale: usize, available: usize) -> usize {
    let w = measure(text, scale);
    if w >= available {
        0
    } else {
        (available - w) / 2
    }
}

