#[inline(always)]
pub fn blend(fg: u32, bg: u32, alpha: u8) -> u32 {
    if alpha == 255 {
        return fg;
    }
    if alpha == 0 {
        return bg;
    }
    let a = alpha as u32;
    let inv_a = 255 - a;
    let fr = ((fg >> 16) & 0xFF) as usize;
    let fg_c = ((fg >> 8) & 0xFF) as usize;
    let fb = (fg & 0xFF) as usize;

    let br = ((bg >> 16) & 0xFF) as usize;
    let bg_c = ((bg >> 8) & 0xFF) as usize;
    let bb = (bg & 0xFF) as usize;

    let fr_lin = SRGB_TO_LIN[fr] as u32;
    let fg_lin = SRGB_TO_LIN[fg_c] as u32;
    let fb_lin = SRGB_TO_LIN[fb] as u32;

    let br_lin = SRGB_TO_LIN[br] as u32;
    let bg_lin = SRGB_TO_LIN[bg_c] as u32;
    let bb_lin = SRGB_TO_LIN[bb] as u32;

    let r_lin = (fr_lin * a + br_lin * inv_a + 127) / 255;
    let g_lin = (fg_lin * a + bg_lin * inv_a + 127) / 255;
    let b_lin = (fb_lin * a + bb_lin * inv_a + 127) / 255;

    let r = LIN_TO_SRGB[r_lin.min(1023) as usize];
    let g = LIN_TO_SRGB[g_lin.min(1023) as usize];
    let b = LIN_TO_SRGB[b_lin.min(1023) as usize];

    0xFF00_0000 | ((r as u32) << 16) | ((g as u32) << 8) | (b as u32)
}

/// Standard proportional text hit-test returning solid ink color if hit.
#[inline(always)]
pub fn test_text(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
) -> Option<u32> {
    if scale == 0 || text.is_empty() {
        return None;
    }
    let dy = y.checked_sub(y0)?;
    let row = dy / scale;
    if row >= GLYPH_H {
        return None;
    }
    let dx = x.checked_sub(x0)?;
    let mut pen = 0usize;
    for &c in text {
        let adv = advance_of(c, false) * scale;
        if dx < pen + adv {
            let col = (dx - pen) / scale;
            return if pixel(c, col, row, false) {
                Some(color)
            } else {
                None
            };
        }
        pen += adv;
    }
    None
}

/// Proportional text test with bold weight.
#[inline(always)]
pub fn test_text_bold(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
) -> Option<u32> {
    if scale == 0 || text.is_empty() {
        return None;
    }
    let dy = y.checked_sub(y0)?;
    let row = dy / scale;
    if row >= GLYPH_H {
        return None;
    }
    let dx = x.checked_sub(x0)?;
    let mut pen = 0usize;
    for &c in text {
        let adv = advance_of(c, true) * scale;
        if dx < pen + adv {
            let col = (dx - pen) / scale;
            return if pixel(c, col, row, true) {
                Some(color)
            } else {
                None
            };
        }
        pen += adv;
    }
    None
}

/// High-definition anti-aliased text renderer driven by true glyph coverage.
///
/// Each glyph cell carries a 4-bit coverage level 0..=15 (see [`FONT_COV`]).
/// Level 0 is transparent, level 15 is solid ink, and levels 1..=14 blend
/// `color` toward `bg` with alpha `level * 17` -- a sixteen-step ramp, which is
/// what keeps a glyph edge from contouring into visible bands. Because the
/// coverage comes from the same supersampled raster the 1-bit tables threshold,
/// edges land on intermediate tones exactly where the outline crosses the pixel
/// instead of stair-stepping, which is what makes text read as type rather than
/// as blocks. Integer `scale` upscales the covered glyph with nearest neighbour:
/// the source pixels are anti-aliased, the magnification stays sharp.
/// The colour of `(x, y)` if `text` inks it, drawn at the size the scale
/// rung names in the design document.
///
/// WHY this delegates to the outline face: the rungs used to name multiples
/// of the bitmap cell, whose caps are more than double the design
/// document's sizes for every rung above the first, and that is what made
/// every reserved box overflow its neighbour. The rungs now name the
/// design's cap heights (`cap_for_scale`), the outline face draws them
/// sharp at the panel's own resolution, and the bitmap face below
/// (`test_glyph_aa`) remains for runs the outline face refuses.
pub fn test_text_aa(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
    bg: u32,
    bold: bool,
) -> Option<u32> {
    crate::design::monochrome::text_px(x, y, x0, y0, cap_for_scale(scale), text, color, bg, bold)
}

/// [`test_text_aa`] at the published text-size level.
///
/// WHY a second entry point and not a change to the first: a caller that keeps
/// its boxes at the platform rung keeps its ink there too, and an app that
/// draws at a scaled cap inside an unscaled box clips the scaled cap. The pair
/// is therefore opt-in per surface: a surface that re-derives its geometry
/// through [`line_height_user`] draws with this, and one that does not keeps
/// [`test_text_aa`]. At the default level the two answer identically, because
/// [`cap_for_scale_user`] is [`cap_for_scale`].
pub fn test_text_aa_user(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
    bg: u32,
    bold: bool,
) -> Option<u32> {
    crate::design::monochrome::text_px(
        x,
        y,
        x0,
        y0,
        cap_for_scale_user(scale),
        text,
        color,
        bg,
        bold,
    )
}

/// The bitmap cell face, renamed to make its role explicit.
///
/// [`test_text_aa`] now means "the size the design document names". This
/// body kept its engine because a run the outline face refuses -- a
/// character the typeface has no outline for -- has to be drawn somehow,
/// and the bitmap cell is what it is drawn with.
#[inline(always)]
pub fn test_glyph_aa(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
    bg: u32,
    bold: bool,
) -> Option<u32> {
    if scale == 0 || text.is_empty() {
        return None;
    }
    let dy = y.checked_sub(y0)?;
    let row = dy / scale;
    if row >= GLYPH_H {
        return None;
    }
    let dx = x.checked_sub(x0)?;
    let mut pen = 0usize;
    for &c in text {
        let adv = advance_of(c, bold) * scale;
        if dx < pen + adv {
            let col = (dx - pen) / scale;
            match coverage(c, col, row, bold) {
                0 => return None,
                15 => return Some(color),
                level => return Some(blend(color, bg, (level * 17) as u8)),
            }
        }
        pen += adv;
    }
    None
}

/// Truncates `text` with an ellipsis ("...") if it exceeds `max_w` at `scale`.
/// Writes into `out_buf` and returns the number of bytes written.
pub fn ellipsize<'a>(text: &[u8], scale: usize, max_w: usize, out_buf: &mut [u8]) -> usize {
    if text.is_empty() {
        return 0;
    }
    let total_w = measure(text, scale);
    if total_w <= max_w {
        let len = text.len().min(out_buf.len());
        out_buf[..len].copy_from_slice(&text[..len]);
        return len;
    }

    let dots = b"...";
    let dots_w = measure(dots, scale);
    if dots_w > max_w || out_buf.len() < 3 {
        return 0;
    }

    // The trim budget is spent in the outline face's advances, so the
    // truncated run's width is the width the renderer will paint.
    let em = em_for_scale(scale);
    let budget = max_w - dots_w;
    let mut current_w = 0usize;
    let mut fit_len = 0usize;

    for (i, &c) in text.iter().enumerate() {
        let adv = crate::design::typeface::advance_px(c, em) as usize;
        if current_w + adv > budget || fit_len + 3 > out_buf.len() {
            break;
        }
        current_w += adv;
        fit_len = i + 1;
    }

    out_buf[..fit_len].copy_from_slice(&text[..fit_len]);
    out_buf[fit_len..fit_len + 3].copy_from_slice(dots);
    fit_len + 3
}

/// Splits `text` into at most `max_lines` line byte slices, breaking at spaces when possible.
pub fn wrap_text<'a>(
    text: &'a [u8],
    scale: usize,
    max_w: usize,
    max_lines: usize,
    out_lines: &mut [&'a [u8]],
) -> usize {
    if text.is_empty() || max_lines == 0 || out_lines.is_empty() {
        return 0;
    }
    let mut line_count = 0;
    let mut start = 0;
    let n = text.len();

    while start < n && line_count < max_lines && line_count < out_lines.len() {
        while start < n && text[start] == b' ' {
            start += 1;
        }
        if start >= n {
            break;
        }

        let mut end = start;
        let mut last_break = None;
        let mut cur_w = 0usize;

        while end < n {
            let c = text[end];
            let adv = advance_of(c, false) * scale;
            if cur_w + adv > max_w && end > start {
                break;
            }
            cur_w += adv;
            if c == b' ' {
                last_break = Some(end);
            }
            end += 1;
        }

        let line_end = if end >= n {
            n
        } else if let Some(brk) = last_break {
            brk
        } else {
            end
        };

        out_lines[line_count] = &text[start..line_end];
        line_count += 1;
        start = line_end;
    }

    line_count
}

/// Renders a text pixel with optional clipping rectangle (x_min, y_min, x_max, y_max).
#[inline(always)]
pub fn test_text_clipped(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
    clip: Option<(usize, usize, usize, usize)>,
) -> Option<u32> {
    if let Some((cx0, cy0, cx1, cy1)) = clip {
        if x < cx0 || x >= cx1 || y < cy0 || y >= cy1 {
            return None;
        }
    }
    test_text(x, y, x0, y0, scale, text, color)
}

/// Returns `Some((character, col, row))` if the pixel at (x, y) contains ink
/// from `text` placed at (x0, y0) with scale and weight, or `None` otherwise.
#[inline]
pub fn run_pixel(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    bold: bool,
) -> Option<(u8, usize, usize)> {
    if scale == 0 || text.is_empty() {
        return None;
    }
    let row = (y.checked_sub(y0)?) / scale;
    if row >= GLYPH_H {
        return None;
    }
    let dx = x.checked_sub(x0)?;
    let mut pen = 0usize;
    for &c in text {
        let adv = advance_of(c, bold) * scale;
        if dx < pen + adv {
            let col = (dx - pen) / scale;
            return if pixel(c, col, row, bold) {
                Some((c, col, row))
            } else {
                None
            };
        }
        pen += adv;
    }
    None
}

/// Maximum buffer capacity for fitted text runs.
pub const RUN_CAP: usize = 96;

/// Truncates `text` with ellipsis "..." to fit within `max_w` pixels at `scale`.
pub fn fit(text: &[u8], scale: usize, max_w: usize, out: &mut [u8]) -> usize {
    if text.is_empty() || out.is_empty() || scale == 0 {
        return 0;
    }
    if measure(text, scale) <= max_w {
        let n = text.len().min(out.len());
        out[..n].copy_from_slice(&text[..n]);
        return n;
    }
    const DOTS: &[u8] = b"...";
    let dots = measure(DOTS, scale);
    if dots > max_w || out.len() < 3 {
        return 0;
    }
    let budget = max_w - dots;
    let mut used = 0usize;
    let mut taken = 0usize;
    for (i, &c) in text.iter().enumerate() {
        let adv = advance_of(c, false) * scale;
        if used + adv > budget || taken + 3 > out.len() {
            break;
        }
        used += adv;
        taken = i + 1;
    }
    out[..taken].copy_from_slice(&text[..taken]);
    out[taken..taken + 3].copy_from_slice(DOTS);
    taken + 3
}

/// Measures fitted width of `text` after applying ellipsis truncation to `max_w`.
#[inline]
pub fn fit_width(text: &[u8], scale: usize, max_w: usize) -> usize {
    let mut buf = [0u8; RUN_CAP];
    let n = fit(text, scale, max_w, &mut buf);
    measure(&buf[..n], scale)
}

/// Tests whether pixel (x, y) contains ink from text run placed at (x0, y0),
/// using outline typography when available, falling back to antialiased bitmap font.
#[inline]
pub fn ink(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    max_w: usize,
    color: u32,
    bg: u32,
) -> bool {
    if scale == 0 {
        return false;
    }
    let h = line_height(scale);
    if y < y0 || y >= y0 + h || x < x0 || x >= x0 + max_w {
        return false;
    }
    let mut buf = [0u8; RUN_CAP];
    let n = fit(text, scale, max_w, &mut buf);
    if n == 0 {
        return false;
    }
    let fitted = &buf[..n];

    let em = crate::design::outline_text::em_for_scale(scale);
    let (asc, _) = crate::design::typeface::line_metrics(em);
    let baseline = (y0 + BASELINE * scale).max(asc as usize);
    if let Some(run) = crate::design::outline_text::OutlineRun::place(x0, baseline, em, fitted) {
        if run.pixel(x, y, color, bg).is_some() {
            return true;
        }
    }

    test_text_aa(x, y, x0, y0, scale, fitted, color, bg, false).is_some()
}

/// Measured width of `text` at `scale` in the given weight.
#[inline]
pub fn width(text: &[u8], scale: usize, bold: bool) -> usize {
    if bold {
        measure_bold(text, scale)
    } else {
        measure(text, scale)
    }
}

/// Measures the advance width of `text` at `scale` with given weight.
#[inline]
pub fn measure_weighted(text: &[u8], scale: usize, bold: bool) -> usize {
    width(text, scale, bold)
}

/// Truncates `text` with ellipsis "..." to fit within `max_w` pixels at `scale` with optional bold.
pub fn fit_weighted(text: &[u8], scale: usize, max_w: usize, bold: bool, out: &mut [u8]) -> usize {
    if text.is_empty() || out.is_empty() || scale == 0 {
        return 0;
    }
    if width(text, scale, bold) <= max_w {
        let n = text.len().min(out.len());
        out[..n].copy_from_slice(&text[..n]);
        return n;
    }
    const DOTS: &[u8] = b"...";
    let dots = width(DOTS, scale, bold);
    if dots > max_w || out.len() < 3 {
        return 0;
    }
    let budget = max_w - dots;
    let mut used = 0usize;
    let mut taken = 0usize;
    for (i, &c) in text.iter().enumerate() {
        let adv = advance_of(c, bold) * scale;
        if used + adv > budget || taken + 3 > out.len() {
            break;
        }
        used += adv;
        taken = i + 1;
    }
    out[..taken].copy_from_slice(&text[..taken]);
    out[taken..taken + 3].copy_from_slice(DOTS);
    taken + 3
}

/// Measures fitted width of `text` after applying ellipsis truncation to `max_w` with optional bold.
#[inline]
pub fn fit_width_weighted(text: &[u8], scale: usize, max_w: usize, bold: bool) -> usize {
    let mut buf = [0u8; RUN_CAP];
    let n = fit_weighted(text, scale, max_w, bold, &mut buf);
    width(&buf[..n], scale, bold)
}

/// Returns Some(color) if pixel (x, y) contains ink from text run placed at (x0, y0).
#[inline]
pub fn ink_option(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    max_w: usize,
    color: u32,
    bg: u32,
    bold: bool,
) -> Option<u32> {
    if scale == 0 {
        return None;
    }
    let h = line_height(scale);
    if y < y0 || y >= y0 + h || x < x0 || x >= x0 + max_w {
        return None;
    }
    let mut buf = [0u8; RUN_CAP];
    let n = fit_weighted(text, scale, max_w, bold, &mut buf);
    if n == 0 {
        return None;
    }
    if let Some(run) = crate::design::outline_text::place_run(x0, y0, scale, &buf[..n], Some(max_w), bold) {
        return run.pixel(x, y, color, bg);
    }
    test_text_aa(x, y, x0, y0, scale, &buf[..n], color, bg, bold)
}

/// Centered text ink inside [x0, x0 + max_w).
#[inline]
pub fn ink_center(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    max_w: usize,
    color: u32,
    bg: u32,
    bold: bool,
) -> Option<u32> {
    let w = fit_width_weighted(text, scale, max_w, bold);
    let cx = x0 + max_w.saturating_sub(w) / 2;
    ink_option(x, y, cx, y0, scale, text, max_w, color, bg, bold)
}

/// Right-aligned text ink ending at x1.
#[inline]
pub fn ink_right(
    x: usize,
    y: usize,
    x1: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    max_w: usize,
    color: u32,
    bg: u32,
    bold: bool,
) -> Option<u32> {
    let w = fit_width_weighted(text, scale, max_w, bold);
    let x0 = x1.saturating_sub(w);
    ink_option(x, y, x0, y0, scale, text, max_w, color, bg, bold)
}

/// Measures text width using the native Full HD (24x36) condensed sans-serif face.
#[inline]
pub fn measure_fhd(text: &[u8]) -> usize {
    let mut w = 0usize;
    for &c in text {
        w += fhd::advance_of(c);
    }
    w
}

/// Standard hit-test and anti-aliased blend using the native Full HD (24x36) face.
#[inline]
pub fn test_text_fhd_aa(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    text: &[u8],
    color: u32,
    bg: u32,
) -> Option<u32> {
    fhd::test_text_aa(x, y, x0, y0, text, color, bg)
}

/// Returns true if the byte can be directly rendered by the font face (ASCII 32..=126).
#[inline]
pub fn is_drawable(b: u8) -> bool {
    b >= FIRST_CHAR && b <= LAST_CHAR
}

/// Transliterates common Unicode codepoints (Latin-1, typographic quotes, dashes,
/// arrows, symbols) into authoritative ASCII equivalents supported by InterOS typography.
pub fn transliterate(cp: u32) -> &'static [u8] {
    match cp {
        // Typographic quotes
        0x2018 | 0x2019 | 0x201B => b"'",
        0x201C | 0x201D | 0x201F => b"\"",
        0x201A => b",",
        0x201E => b",,",
        0x00AB | 0x00BB => b"\"",

        // Dashes & hyphens
        0x2010 | 0x2011 | 0x2012 | 0x2013 => b"-",
        0x2014 | 0x2015 => b"--",
        0x2212 => b"-", // minus sign

        // Ellipsis & bullets
        0x2026 => b"...",
        0x2022 | 0x00B7 => b".",

        // Arrows
        0x2190 => b"<-",
        0x2192 => b"->",
        0x2194 => b"<->",
        0x21D2 => b"=>",

        // Symbols & currency
        0x00D7 => b"x",
        0x00F7 => b"/",
        0x00B0 => b"deg",
        0x00A9 => b"(c)",
        0x00AE => b"(r)",
        0x2122 => b"(tm)",
        0x00B1 => b"+/-",
        0x2264 => b"<=",
        0x2265 => b">=",
        0x2260 => b"!=",
        0x00A3 => b"GBP",
        0x20AC => b"EUR",
        0x00A5 => b"JPY",
        0x00A2 => b"c",

        // Whitespace variants
        0x00A0 | 0x2002 | 0x2003 | 0x2009 | 0x202F => b" ",

        // Latin-1 Uppercase Accents
        0x00C0..=0x00C5 => b"A",
        0x00C6 => b"AE",
        0x00C7 => b"C",
        0x00C8..=0x00CB => b"E",
        0x00CC..=0x00CF => b"I",
        0x00D0 => b"D",
        0x00D1 => b"N",
        0x00D2..=0x00D6 | 0x00D8 => b"O",
        0x00D9..=0x00DC => b"U",
        0x00DD => b"Y",
        0x00DE => b"TH",

        // Latin-1 Lowercase Accents
        0x00DF => b"ss",
        0x00E0..=0x00E5 => b"a",
        0x00E6 => b"ae",
        0x00E7 => b"c",
        0x00E8..=0x00EB => b"e",
        0x00EC..=0x00EF => b"i",
        0x00F0 => b"d",
        0x00F1 => b"n",
        0x00F2..=0x00F6 | 0x00F8 => b"o",
        0x00F9..=0x00FC => b"u",
        0x00FD | 0x00FF => b"y",
        0x00FE => b"th",

        _ => b"",
    }
}

/// Renders an anti-aliased text pixel with horizontal budget clipping at `x0 + max_w`.
#[inline(always)]
pub fn test_text_aa_clipped(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    text: &[u8],
    color: u32,
    bg: u32,
    bold: bool,
    max_w: usize,
) -> Option<u32> {
    if x >= x0.saturating_add(max_w) {
        return None;
    }
    test_text_aa(x, y, x0, y0, scale, text, color, bg, bold)
}

/// Measures the combined horizontal advance of a slice of styled runs `(text, bold)`.
pub fn measure_runs(runs: &[(&[u8], bool)], scale: usize) -> usize {
    let mut total_w = 0usize;
    for &(text, bold) in runs {
        total_w += measure_weighted(text, scale, bold);
    }
    total_w
}

/// Renders a sequence of styled runs `(text, bold)` along a shared horizontal baseline.
pub fn test_text_aa_runs(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    scale: usize,
    runs: &[(&[u8], bool)],
    color: u32,
    bg: u32,
) -> Option<u32> {
    let mut pen = x0;
    for &(text, bold) in runs {
        let run_w = measure_weighted(text, scale, bold);
        if x >= pen && x < pen + run_w {
            return test_text_aa(x, y, pen, y0, scale, text, color, bg, bold);
        }
        pen += run_w;
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_glyph_measurement() {
        let m_a = measure(b"A", 1);
        let m_w = measure(b"W", 1);
        let m_i = measure(b"i", 1);
        assert!(m_w > m_i, "W should be wider than i");
        assert!(m_a > m_i, "A should be wider than i");
        assert_eq!(measure(b"Ai", 1), m_a + m_i);
        // WHY the second rung is not doubled: the rung names a cap height,
        // and successive rungs are the design document's sizes rather than
        // exact multiples of one another, so a run's width grows with the
        // em it is drawn at, not with the rung number.
        let m2_a = measure(b"A", 2);
        let m2_i = measure(b"i", 2);
        assert!(m2_a > m_a, "body type is wider than caption type");
        assert_eq!(measure(b"Ai", 2), m2_a + m2_i);
    }

    #[test]
    fn test_proportional_widths() {
        let adv_i = advance_of(b'i', false);
        let adv_m = advance_of(b'm', false);
        let adv_w = advance_of(b'W', false);
        assert!(adv_m > adv_i, "m should advance more than i");
        assert!(adv_w > adv_i, "W should advance more than i");
    }

    #[test]
    fn test_digit_tabular_widths() {
        let adv_0 = advance_of(b'0', false);
        for d in b'1'..=b'9' {
            assert_eq!(
                advance_of(d, false),
                adv_0,
                "Digit '{}' must have tabular advance equal to '0'",
                d as char
            );
        }
    }

    #[test]
    fn test_centering() {
        let text = b"Settings";
        let width = 720;
        let c_x = center_x(text, 2, width);
        let text_w = measure(text, 2);
        assert_eq!(c_x, (width - text_w) / 2);
    }

    #[test]
    fn test_wrapping() {
        let text = b"The quick brown fox jumps over the lazy dog";
        let mut lines = [&b""[..]; 4];
        let count = wrap_text(text, 1, 100, 4, &mut lines);
        assert!(count >= 2, "Text should wrap into multiple lines");
        for line in &lines[..count] {
            assert!(measure(line, 1) <= 100, "Wrapped line must fit in width limit");
        }
    }

    #[test]
    fn test_ellipsization() {
        let text = b"Very long application title that exceeds width";
        let mut buf = [0u8; 64];
        let written = ellipsize(text, 1, 80, &mut buf);
        assert!(written > 0);
        let result = &buf[..written];
        assert!(result.ends_with(b"..."), "Result must end with ellipsis");
        assert!(measure(result, 1) <= 80, "Ellipsized text must fit in max width");
    }

    #[test]
    fn test_clipping() {
        let text = b"ClipTest";
        // Inside clip rect
        let color = 0xFF112233;
        let p_inside = test_text_clipped(10, 10, 0, 0, 1, text, color, Some((5, 5, 50, 50)));
        // Outside clip rect
        let p_outside = test_text_clipped(2, 2, 0, 0, 1, text, color, Some((5, 5, 50, 50)));
        assert_eq!(p_outside, None, "Point outside clip rect must be None");
        let _ = p_inside;
    }

    #[test]
    fn test_baseline() {
        assert!(BASELINE < GLYPH_H);
        assert!(CAP_TOP < BASELINE);
        assert!(DESCENDER >= BASELINE);
    }

    #[test]
    fn test_coverage_agrees_with_pixel() {
        // The binary ink view is `coverage >= 8` by construction (the 4-bit
        // levels quantise the same supersampled source the 1-bit tables
        // threshold at 0.5), so layout maths (`pixel`) and rendering
        // (`test_text_aa`) can never disagree about what is ink.
        for c in FIRST_CHAR..=LAST_CHAR {
            for row in 0..GLYPH_H {
                for col in 0..GLYPH_W {
                    for bold in [false, true] {
                        let ink = pixel(c, col, row, bold);
                        let level = coverage(c, col, row, bold);
                        assert!(level <= 15, "coverage level out of range");
                        assert_eq!(ink, level >= 8,
                            "pixel/coverage disagree at {:?} col {} row {} bold {}",
                            c as char, col, row, bold);
                    }
                }
            }
        }
    }

    #[test]
    fn test_aa_uses_intermediate_tones() {
        // Proves the coverage tables carry real edge data: the face must hold
        // cells across a wide span of the 16-step ramp -- not merely one or two
        // partial tones -- and the blitter must turn them into blends rather
        // than hard on/off pixels.
        let mut partials = 0u32;
        let mut distinct = [false; 16];
        for c in FIRST_CHAR..=LAST_CHAR {
            for row in 0..GLYPH_H {
                for col in 0..GLYPH_W {
                    let level = coverage(c, col, row, false) as usize;
                    if level != 0 && level != 15 {
                        partials += 1;
                        distinct[level] = true;
                    }
                }
            }
        }
        assert!(partials > 0, "face has no anti-aliased edge cells");
        let tones = distinct.iter().filter(|&&d| d).count();
        assert!(tones >= 6,
            "only {} distinct edge tones; a 16-step ramp should span many more",
            tones);
        // Spot-check the blend mapping level*17 on a known partial cell.
        let mut checked = false;
        for c in FIRST_CHAR..=LAST_CHAR {
            for row in 0..GLYPH_H {
                for col in 0..GLYPH_W {
                    let level = coverage(c, col, row, false);
                    if level != 0 && level != 15 {
                        let fg = 0xFFFFFFFF;
                        let bg = 0xFF000000;
                        let got = blend(fg, bg, (level * 17) as u8);
                        assert_ne!(got, fg);
                        assert_ne!(got, bg);
                        checked = true;
                        break;
                    }
                }
                if checked {
                    break;
                }
            }
            if checked {
                break;
            }
        }
        assert!(checked);
    }

    #[test]
    fn test_rasterization_bounds() {
        let text = b"X";
        // Far outside should be None
        assert_eq!(test_text(1000, 1000, 0, 0, 1, text, 0xFFFFFFFF), None);
        assert_eq!(test_text(0, 30, 0, 0, 1, text, 0xFFFFFFFF), None);
    }

    #[test]
    fn test_transliteration_and_drawable() {
        assert!(is_drawable(b'A'));
        assert!(is_drawable(b' '));
        assert!(!is_drawable(0x80));
        assert_eq!(transliterate(0x2018), b"'");
        assert_eq!(transliterate(0x2014), b"--");
        assert_eq!(transliterate(0x2026), b"...");
        assert_eq!(transliterate(0x2192), b"->");
        assert_eq!(transliterate(0x00E9), b"e");
        assert_eq!(transliterate(0x00A9), b"(c)");
    }

    #[test]
    fn test_text_aa_clipped_budget() {
        let text = b"Long test string exceeding budget";
        let x0 = 10usize;
        let max_w = 40usize;
        // Pixel at or beyond x0 + max_w must be None
        for py in 0..24 {
            for px in (x0 + max_w)..(x0 + max_w + 100) {
                assert_eq!(
                    test_text_aa_clipped(px, py, x0, 0, 1, text, 0xFFFFFFFF, 0xFF000000, false, max_w),
                    None
                );
            }
        }
    }

    #[test]
    fn test_wrap_text_contract() {
        let text = b"The InterOS Core kernel is a capability-secure microkernel designed for mobile devices. It provides high performance without heap allocation in render paths and event loops, ensuring zero-latency interactivity.";
        assert!(text.len() >= 200, "Text length must be >= 200 bytes for contract");
        let mut lines = [&b""[..]; 8];
        let count = wrap_text(text, 1, 600, 8, &mut lines);
        assert!(count >= 2, "Expected multiple wrapped lines");
        for line in &lines[..count] {
            let line_w = measure(line, 1);
            assert!(line_w <= 600, "Wrapped line exceeds 600px: {line_w}px");
        }
    }

    #[test]
    fn test_measure_and_render_mixed_runs() {
        let runs: &[(&[u8], bool)] = &[
            (b"Hello ", false),
            (b"World", true),
            (b"!", false),
        ];
        let total_w = measure_runs(runs, 1);
        let expected = measure(b"Hello ", 1) + measure_bold(b"World", 1) + measure(b"!", 1);
        assert_eq!(total_w, expected);

        // Spot test rendering within the run
        let hit = test_text_aa_runs(10, 10, 0, 0, 1, runs, 0xFFFFFFFF, 0xFF000000);
        let _ = hit;
    }

    #[test]
    fn test_user_text_scale_dynamic_scaling() {
        // Test all scale rungs across user text scales
        for rung in 1..=6 {
            let base = cap_for_scale(rung);
            let compact = cap_for_user_scale(rung, TEXT_SCALE_COMPACT);
            let normal = cap_for_user_scale(rung, TEXT_SCALE_NORMAL);
            let large = cap_for_user_scale(rung, TEXT_SCALE_LARGE);
            let extra_large = cap_for_user_scale(rung, TEXT_SCALE_EXTRA_LARGE);

            assert_eq!(normal, base);
            assert!(compact <= normal, "Compact must be <= normal");
            assert!(compact >= 10, "Compact cap height must stay >= 10px minimum bound");
            assert!(normal <= large, "Normal must be <= large");
            assert!(large <= extra_large, "Large must be <= extra large");

            // cap_for_scale_with_user alias agrees
            assert_eq!(cap_for_scale_with_user(rung, TEXT_SCALE_LARGE), large);

            // Out-of-bounds scale clamped to extra large
            assert_eq!(cap_for_user_scale(rung, 10), extra_large);
        }

        // Test dynamic measurement
        let text = b"Settings";
        let w_compact = measure_user_scale(text, 2, TEXT_SCALE_COMPACT);
        let w_normal = measure_user_scale(text, 2, TEXT_SCALE_NORMAL);
        let w_large = measure_user_scale(text, 2, TEXT_SCALE_LARGE);
        assert!(w_compact <= w_normal);
        assert!(w_normal <= w_large);
    }
}

